interface.definition:
#"SYSTEM_SYSRULES_sectionLayout_v1"(
  label: "Inspections Review",
  labelColor: "SECONDARY",
  contents: {
    #"SYSTEM_SYSRULES_richTextDisplayField"(
      labelPosition: "COLLAPSED",
      value: {
        #"SYSTEM_SYSRULES_richTextItem_v1"(
          text: {"To be completed by Inspections"},
          size: "SMALL",
          style: "EMPHASIS"
        )
      }
    ),
    #"SYSTEM_SYSRULES_cardLayout"(
      contents: {
        if(
          ri!nomination.statusId = #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4494074",
          {
            #"SYSTEM_SYSRULES_radioButtonField"(              
              label: "Does this candidate have negative inspections findings (PCAOB/QP)?",
              choiceLabels: {"Yes", "No"},
              choiceValues: {True, False},
              value: ri!nomination.negativeInspectionFindings,
              saveInto: ri!nomination.negativeInspectionFindings,
              required: true,
              choiceLayout: "COMPACT"
            ),
            #"SYSTEM_SYSRULES_paragraphField"(
              label: "Inspections Comments",
              value: ri!nomination.inspectionComments,
              saveInto: ri!nomination.inspectionComments,
              required: ri!nomination.negativeInspectionFindings = true,
              characterLimit: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3238137"
            )            
          },
          {
            #"SYSTEM_SYSRULES_richTextDisplayField"(
              label: "Does this candidate have negative inspections findings (PCAOB/QP)?",
              value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
                value: ri!nomination.negativeInspectionFindings,
                isBoolean: true
              )
            ),
            #"SYSTEM_SYSRULES_richTextDisplayField"(
              label: "Inspections Comments",
              value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
                value: ri!nomination.inspectionComments,
                isBoolean: false
              )
            )
          }            
        )
      }
    )
  },
  isCollapsible: true,
  showWhen: /*if(*/
    /*or(*/
      /*index(ri!nomination,"subPositionTypeId",null) = cons!CAW_INT_NOMINATION_SUBTYPE_POSITION_CORE_MD,*/
      /*index(ri!nomination,"subPositionTypeId",null) = cons!CAW_INT_NOMINATION_SUBTYPE_POSITION_CORE_PARTNER,*/
    /*),*/
    /*false,*/
    ri!showWhen
  /*)*/
)
